  'queue.quItemActionNeedsTicket': { 'zh-Hans': '这一单还没有开工单，请先安排工位入座', 'zh-Hant': "這一單還沒有開工單，請先安排工位入座", en: 'No ticket has been opened yet — seat the guest first', ko: '아직 티켓이 없습니다. 먼저 자리를 배정해 주세요', es: 'Aún no hay ticket: primero asigna puesto al cliente', vi: 'Chưa có phiếu — hãy xếp chỗ cho khách trước' },
