  'queue.quFormNotConfigured': { 'zh-Hans': '本店未配置电子健康问卷', 'zh-Hant': "本店未配置電子健康問卷", en: 'No digital health form is configured for this shop', ko: '이 매장에는 전자 건강 문진표가 설정되어 있지 않습니다', es: 'Esta tienda no tiene un formulario de salud digital', vi: 'Cửa hàng chưa cấu hình phiếu sức khỏe điện tử' },
  'queue.quFormNotConfiguredDesc': { 'zh-Hans': '入座前请口头确认禁忌与过敏，不要把「未配置」当成「已签署」。', 'zh-Hant': "入座前請口頭確認禁忌與過敏，不要把「未配置」當成「已簽署」。", en: 'Confirm contraindications verbally before seating. An unconfigured form is not a signed waiver.', ko: '착석 전에 금기와 알레르기를 구두로 확인하세요. 미설정은 서명 완료가 아닙니다.', es: 'Confirma verbalmente las contraindicaciones antes de sentar. Un formulario no configurado no es un consentimiento firmado.', vi: 'Hãy xác nhận chống chỉ định bằng lời trước khi xếp chỗ. Chưa cấu hình phiếu không có nghĩa là đã ký.' },
  'queue.quFormNotConfiguredBadge': { 'zh-Hans': '未配置问卷', 'zh-Hant': "未配置問卷", en: 'No form configured', ko: '문진표 없음', es: 'Sin formulario', vi: 'Chưa có phiếu' },
