  'queue.quAddOnQuickPick': { 'zh-Hans': '常用加项', 'zh-Hant': "常用加項", en: 'Frequent add-ons', ko: '자주 쓰는 추가 항목', es: 'Extras frecuentes', vi: 'Dịch vụ thêm thường dùng' },
  'queue.quAddOnQuickPickHint': { 'zh-Hans': '点选后请在下方指定提成技师并添加。', 'zh-Hant': "點選後請在下方指定提成技師並添加。", en: 'Pick one, then choose the commission technician below and add it.', ko: '선택한 뒤 아래에서 커미션 담당자를 지정하고 추가하세요.', es: 'Elige uno y luego indica el terapeuta con comisión antes de añadirlo.', vi: 'Chọn xong hãy chỉ định KTV nhận hoa hồng bên dưới rồi thêm.' },
